// Keep only the masks needed for live file:// rendering on the startup path.
const fs = require("node:fs");
const path = require("node:path");
const vm = require("node:vm");
const root = path.resolve(__dirname, "..", "public");
const context = { window: {} };
vm.runInNewContext(fs.readFileSync(path.join(root, "js/ExportAssetData.js"), "utf8"), context);
const arrows = Object.fromEntries(Object.entries(context.window.SIGNMAKER_EXPORT_ASSETS)
  .filter(([name]) => name.startsWith("img/arrowBlocks/")));
fs.writeFileSync(path.join(root, "js/ArrowAssetData.js"),
  "/* Generated by scripts/build-startup-arrow-assets.cjs. Startup masks for file:// signs. */\n" +
  "window.SIGNMAKER_ARROW_ASSETS = " + JSON.stringify(arrows) + ";\n");
console.log("Startup arrow masks:", Object.keys(arrows).length);
